mapper.select:
SELECT * FROM staffs
WHERE business_id = #{businessId}
ORDER BY display_order ASC, created_at ASC

SELECT * FROM staffs
WHERE business_id = #{businessId}
  AND is_active = #{isActive}
ORDER BY display_order ASC, created_at ASC

SELECT EXISTS(
    SELECT 1 FROM staffs WHERE id = #{id}
)

SELECT EXISTS(
    SELECT 1 FROM staffs
    WHERE business_id = #{businessId} AND id = #{id}
)
